"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[7638],{63351:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>i,contentTitle:()=>r,default:()=>u,frontMatter:()=>s,metadata:()=>a,toc:()=>l});var o=h(31085),n=h(71184);const s={sidebar_position:12,slug:"/bible/Luke/Luke_12",title:"Luke 12",hide_table_of_contents:!0},r="Luke",a={id:"bible/Luke/Luke 12",title:"Luke 12",description:"Chapter 12",source:"@site/docs/bible/Luke/Luke 12.md",sourceDirName:"bible/Luke",slug:"/bible/Luke/Luke_12",permalink:"/docs/bible/Luke/Luke_12",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Luke/Luke 12.md",tags:[],version:"current",sidebarPosition:12,frontMatter:{sidebar_position:12,slug:"/bible/Luke/Luke_12",title:"Luke 12",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Luke 11",permalink:"/docs/bible/Luke/Luke_11"},next:{title:"Luke 13",permalink:"/docs/bible/Luke/Luke_13"}},i={},l=[{value:"Chapter 12",id:"chapter-12",level:2}];function d(e){const t={h1:"h1",h2:"h2",p:"p",...(0,n.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h1,{id:"luke",children:"Luke"}),"\n",(0,o.jsx)(t.h2,{id:"chapter-12",children:"Chapter 12"}),"\n",(0,o.jsx)(t.p,{children:"Christ warns us against hypocrisy, the fear of the world and covetousness.  He admonishes all to watch."}),"\n",(0,o.jsx)(h,{verse:1,children:"And when great multitudes stood about him, so that they trod one upon another, he began to say to his disciples: Beware ye of the leaven of the Pharisees, which is hypocrisy."}),"\n",(0,o.jsx)(h,{verse:2,children:"For there is nothing covered that shall not be revealed: nor hidden that shall not be known."}),"\n",(0,o.jsx)(h,{verse:3,children:"For whatsoever things you have spoken in darkness shall be published in the light: and that which you have spoken in the ear in the chambers shall be preached on the housetops."}),"\n",(0,o.jsx)(h,{verse:4,children:"And I say to you, my friends: Be not afraid of them who kill the body and after that have no more that they can do."}),"\n",(0,o.jsx)(h,{verse:5,children:"But I will shew you whom you shall fear: Fear ye him who, after he hath killed, hath power to cast into hell. Yea, I say to you: Fear him."}),"\n",(0,o.jsx)(h,{verse:6,children:"Are not five sparrows sold for two farthings, and not one of them is forgotten before God?"}),"\n",(0,o.jsx)(h,{verse:7,children:"Yea, the very hairs of your head are all numbered. Fear not therefore: you are of more value than many sparrows."}),"\n",(0,o.jsx)(h,{verse:8,children:"And I say to you: Whosoever shall confess me before men, him shall the Son of man also confess before the angels of God."}),"\n",(0,o.jsx)(h,{verse:9,children:"But he that shall deny me before men shall be denied before the angels of God."}),"\n",(0,o.jsx)(h,{verse:10,children:"And whosoever speaketh a word against the Son of man, it shall be forgiven him: but to him that shall blaspheme against the Holy Ghost, it shall not be forgiven."}),"\n",(0,o.jsx)(h,{verse:11,children:"And when they shall bring you into the synagogues and to magistrates and powers, be not solicitous how or what you shall answer, or what you shall say."}),"\n",(0,o.jsx)(h,{verse:12,children:"For the Holy Ghost shall teach you in the same hour what you must say."}),"\n",(0,o.jsx)(h,{verse:13,children:"And one of the multitude said to him: Master, speak to my brother that he divide the inheritance with me."}),"\n",(0,o.jsx)(h,{verse:14,children:"But he said to him: Man, who hath appointed me judge or divider over you?"}),"\n",(0,o.jsx)(h,{verse:15,children:"And he said to them: Take heed and beware of all covetousness: for a man's life doth not consist in the abundance of things which he possesseth."}),"\n",(0,o.jsx)(h,{verse:16,children:"And he spoke a similitude to them, saying: The land of a certain rich man brought forth plenty of fruits."}),"\n",(0,o.jsx)(h,{verse:17,children:"And he thought within himself, saying: What shall I do, because I have no room where to bestow my fruits?"}),"\n",(0,o.jsx)(h,{verse:18,children:"And he said: This will I do: I will pull down my barns and will build greater: and into them will I gather all things that are grown to me and my goods."}),"\n",(0,o.jsx)(h,{verse:19,children:"And I will say to my soul: Soul, thou hast much goods laid up for many years. Take thy rest: eat, drink, make good cheer."}),"\n",(0,o.jsx)(h,{verse:20,children:"But God said to him: Thou fool, this night do they require thy soul of thee. And whose shall those things be which thou hast provided?"}),"\n",(0,o.jsx)(h,{verse:21,children:"So is he that layeth up treasure for himself and is not rich towards God."}),"\n",(0,o.jsx)(h,{verse:22,children:"And he said to his disciples: Therefore I say to you: Be not solicitous for your life, what you shall eat, nor for your body, what you shall put on."}),"\n",(0,o.jsx)(h,{verse:23,children:"The life is more than the meat: and the body is more than the raiment."}),"\n",(0,o.jsx)(h,{verse:24,children:"Consider the ravens, for they sow not, neither do they reap, neither have they storehouse nor barn, and God feedeth them. How much are you more valuable than they?"}),"\n",(0,o.jsx)(h,{verse:25,children:"And which of you by taking thought can add to his stature one cubit?"}),"\n",(0,o.jsx)(h,{verse:26,children:"If then ye be not able to do so much as the least thing, why are you solicitous for the rest?"}),"\n",(0,o.jsx)(h,{verse:27,children:"Consider the lilies, how they grow: they labour not, neither do they spin. But I say to you, not even Solomon in all his glory was clothed like one of these."}),"\n",(0,o.jsx)(h,{verse:28,children:"Now, if God clothe in this manner the grass that is to-day in the field and to-morrow is cast into the oven: how much more you, O ye of little faith?"}),"\n",(0,o.jsx)(h,{verse:29,children:"And seek not what you shall eat or what you shall drink: and be not lifted up on high."}),"\n",(0,o.jsx)(h,{verse:30,children:"For all these things do the nations of the world seek. But your Father knoweth that you have need of these things."}),"\n",(0,o.jsx)(h,{verse:31,children:"But seek ye first the kingdom of God and his justice: and all these things shall be added unto you."}),"\n",(0,o.jsx)(h,{verse:32,children:"Fear not, little flock, for it hath pleased your Father to give you a kingdom."}),"\n",(0,o.jsx)(h,{verse:33,children:"Sell what you possess and give alms. Make to yourselves bags which grow not old, a treasure in heaven which faileth not: where no thief approacheth, nor moth corrupteth."}),"\n",(0,o.jsx)(h,{verse:34,children:"For where your treasure is, there will your heart be also."}),"\n",(0,o.jsx)(h,{verse:35,children:"Let your loins be girt and lamps burning in your hands."}),"\n",(0,o.jsx)(h,{verse:36,children:"And you yourselves like to men who wait for their lord, when he shall return from the wedding; that when he cometh and knocketh, they may open to him immediately."}),"\n",(0,o.jsx)(h,{verse:37,children:"Blessed are those servants whom the Lord, when he cometh, shall find watching. Amen I say to you that he will gird himself and make them sit down to meat and passing will minister unto them."}),"\n",(0,o.jsx)(h,{verse:38,children:"And if he shall come in the second watch or come in the third watch and find them so, blessed are those servants."}),"\n",(0,o.jsx)(h,{verse:39,children:"But this know ye, that if the householder did know at what hour the thief would come, he would surely watch and would not suffer his house to be broken open."}),"\n",(0,o.jsx)(h,{verse:40,children:"Be you then also ready: for at what hour you think not the Son of man will come."}),"\n",(0,o.jsx)(h,{verse:41,children:"And Peter said to him: Lord, dost thou speak this parable to us, or likewise to all?"}),"\n",(0,o.jsx)(h,{verse:42,children:"And the Lord said: Who thinkest thou is the faithful and wise steward, whom his lord setteth over his family, to give them their measure of wheat in due season?"}),"\n",(0,o.jsx)(h,{verse:43,children:"Blessed is that servant whom, when his lord shall come, he shall find so doing."}),"\n",(0,o.jsx)(h,{verse:44,children:"Verily I say to you, he will set him over all that he possesseth."}),"\n",(0,o.jsx)(h,{verse:45,children:"But if that servant shall say in his heart: My Lord is long a coming; and shall begin to strike the men-servants and maid-servants, and to eat and to drink and be drunk:"}),"\n",(0,o.jsx)(h,{verse:46,children:"The lord of that servant will come in the day that he hopeth not, and at the hour that he knoweth not: and shall separate him and shall appoint him his portion with unbelievers."}),"\n",(0,o.jsx)(h,{verse:47,children:"And that servant, who knew the will of his lord and prepared not himself and did not according to his will, shall be beaten with many stripes."}),"\n",(0,o.jsx)(h,{verse:48,children:"But he that knew not and did things worthy of stripes shall be beaten with few stripes. And unto whomsoever much is given, of him much shall be required: and to whom they have committed much, of him they will demand the more."}),"\n",(0,o.jsx)(h,{verse:49,children:"I am come to cast fire on the earth. And what will I, but that it be kindled?"}),"\n",(0,o.jsx)(h,{verse:50,children:"And I have a baptism wherewith I am to be baptized. And how am I straitened until it be accomplished?"}),"\n",(0,o.jsx)(h,{verse:51,children:"Think ye, that I am come to give peace on earth? I tell you, no; but separation."}),"\n",(0,o.jsx)(h,{verse:52,children:"For there shall be from henceforth five in one house divided: three against two, and two against three."}),"\n",(0,o.jsx)(h,{verse:53,children:"The father shall be divided against the son and the son against his father: the mother against the daughter and the daughter against her mother: the mother-in-law against the daughter-in-law and the daughter-in-law against her mother-in-law."}),"\n",(0,o.jsx)(h,{verse:54,children:"And he said also to the multitudes: When you see a cloud rising from the west, presently you say: A shower is coming. And so it happeneth."}),"\n",(0,o.jsx)(h,{verse:55,children:"And when ye see the south wind blow, you say: There will heat. And it cometh to pass."}),"\n",(0,o.jsx)(h,{verse:56,children:"You hypocrites, you know how to discern the face of the heaven and of the earth: but how is it that you do not discern this time?"}),"\n",(0,o.jsx)(h,{verse:57,children:"And why, even of yourselves, do you not judge that which is just?"}),"\n",(0,o.jsx)(h,{verse:58,children:"And when thou goest with thy adversary to the prince, whilst thou art in the way, endeavour to be delivered from him: lest perhaps he draw thee to he judge, and the judge deliver thee to the exacter, and the exacter cast thee into prison."}),"\n",(0,o.jsx)(h,{verse:59,children:"I say to thee, thou shalt not go out thence until thou pay the very last mite."})]})}function u(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>r,x:()=>a});var o=h(14041);const n={},s=o.createContext(n);function r(e){const t=o.useContext(s);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);